pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with very little space left
    if bin_residual < 10 {
        score += 8.0 * (10 - bin_residual) as f64;
    }

    // Reward filling bins close to capacity
    if bin_capacity - bin_residual < 20 {
        score -= 4.0 * ((bin_capacity - bin_residual) as f64 / 20.0);
    }

    // Penalize unused space in open bins
    if mean_residual > 55.0 {
        score += 1.2 * (mean_residual - 55.0);
    }

    // Reward fitting items in existing bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Penalize lookahead items that would waste space
    if next_item_size > 0 && (bin_capacity - post_residual) < next_item_size {
        score += 4.0 * next_item_size as f64 / (bin_capacity - bin_residual) as f64;
    }

    // Reward using fewer bins overall
    score -= 0.15 * open_bins_count as f64;

    score
}

