pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize bins that are almost full but not fully utilized
    if bin_capacity - item_size < 5 && bin_capacity - item_size > 1 {
        score += (bin_capacity - item_size) as f64;
    }

    // Reward efficient use of bins based on mean residual
    if post_residual > mean_residual * 2.0 {
        score -= (post_residual - mean_residual * 2.0) as f64;
    }

    // Penalize excess open bins
    if open_bins_count > total_items / 10 {
        score += (open_bins_count - total_items / 10) as f64;
    }

    // Reward fitting items in existing bins
    if fitting_bins_count > 0 {
        score -= 0.25 * (fitting_bins_count as f64);
    }

    // Penalize lookahead items that cannot fit in any open bin
    if next_item_size != 0 && fitting_bins_count == 0 {
        score += next_item_size as f64;
    }

    // Reward using the first available bin when possible
    if step_index == 0 {
        score -= 1.25;
    }

    // Penalize bins that are exactly half full
    if post_residual == bin_capacity / 2 {
        score += 0.5 * (bin_capacity as f64);
    }

    score
}

